+          _isTranslating = false;
+        });
+      }
+    } catch (e) {
+      if (kDebugMode) print('Translation error: $e');
+      if (mounted) {
+        setState(() {
+          _isTranslating = false;
+        });
+      }
+    }
+  }
+
+  void _toggleLanguage() {
+    setState(() {
+      _showGerman = !_showGerman;
+    });
+  }
+
+  String get _currentDescription {
